Looking at this problem:

- Build an undirected graph of "dislikes" (the relation is symmetric).
- This is a **bipartite 2-coloring** problem: two students who dislike each other must be in different teams.
- Student 1 goes to team 1; BFS/DFS from student 1 assigns teams alternately. A connected bipartite component has exactly one such coloring (matching both examples — in example 2 the star centered at 13 forces 13 to team 2 and everyone else to team 1, exactly as in the expected output).
- For robustness, any component not reachable from 1 is seeded with its smallest-index student in team 1.
- Must be efficient: N up to 10⁵, ΣM up to 6×10⁵ → use fast input parsing and CSR adjacency, BFS iteratively, output both teams sorted ascending.

Verified against both examples (produces exactly the expected outputs).

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    // Read entire stdin
    size_t cap = 1 << 22;
    char *data = (char *)malloc(cap);
    size_t len = 0;
    for (;;) {
        if (len == cap) { cap <<= 1; data = (char *)realloc(data, cap); }
        size_t r = fread(data + len, 1, cap - len, stdin);
        if (r == 0) break;
        len += r;
    }

    size_t pos = 0;
    auto readInt = [&]() -> int {
        while (pos < len && (data[pos] < '0' || data[pos] > '9')) ++pos;
        int x = 0;
        while (pos < len && data[pos] >= '0' && data[pos] <= '9') {
            x = x * 10 + (data[pos] - '0');
            ++pos;
        }
        return x;
    };

    int N = readInt();

    // Pass 1: compute degrees
    vector<int> deg(N + 2, 0);
    size_t savedPos = pos;
    for (int i = 1; i <= N; ++i) {
        int M = readInt();
        for (int j = 0; j < M; ++j) {
            int x = readInt();
            ++deg[i];
            ++deg[x];
        }
    }

    vector<int> start(N + 2, 0);
    for (int v = 1; v <= N; ++v) start[v + 1] = start[v] + deg[v];

    vector<int> adj((size_t)start[N + 1]);
    pos = savedPos;
    {
        vector<int> ptr(start.begin(), start.begin() + (N + 1));
        for (int i = 1; i <= N; ++i) {
            int M = readInt();
            for (int j = 0; j < M; ++j) {
                int x = readInt();
                adj[ptr[i]++] = x;
                adj[ptr[x]++] = i;
            }
        }
    }

    // BFS 2-coloring: team 1 and team 2
    vector<int> color(N + 1, 0);
    vector<int> q;
    q.reserve(N);
    for (int s = 1; s <= N; ++s) {
        if (color[s] != 0) continue;
        color[s] = 1;
        q.clear();
        q.push_back(s);
        for (size_t qi = 0; qi < q.size(); ++qi) {
            int u = q[qi];
            int nc = 3 - color[u];
            for (int e = start[u]; e < start[u + 1]; ++e) {
                int w = adj[e];
                if (color[w] == 0) {
                    color[w] = nc;
                    q.push_back(w);
                }
            }
        }
    }

    // Output
    string out;
    out.reserve((size_t)N * 8 + 4);
    char tmp[12];
    auto addNum = [&](int v) {
        int k = 0;
        do { tmp[k++] = (char)('0' + v % 10); v /= 10; } while (v);
        while (k) out.push_back(tmp[--k]);
    };
    bool first = true;
    for (int i = 1; i <= N; ++i) {
        if (color[i] == 1) {
            if (!first) out.push_back(' ');
            addNum(i);
            first = false;
        }
    }
    out.push_back('\n');
    first = true;
    for (int i = 1; i <= N; ++i) {
        if (color[i] == 2) {
            if (!first) out.push_back(' ');
            addNum(i);
            first = false;
        }
    }
    out.push_back('\n');

    fwrite(out.data(), 1, out.size(), stdout);

    free(data);
    return 0;
}
```

